package com.loyu3c.rental;
import org.json.*;import java.util.*;
public final class Owners {
    public static JSONArray rows(JSONObject b,String key){JSONArray a=b.optJSONArray(key);return a==null?new JSONArray():a;}
    public static JSONObject find(JSONArray rows,String id)throws JSONException{for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).optString("id")))return rows.getJSONObject(i);return null;}
    public static boolean email(String value){return value!=null&&value.matches("[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@(?i:gmail\\.com)");}
    public static void validate(JSONObject b)throws JSONException{Set<String> ids=new HashSet<>();JSONArray owners=rows(b,"owners");for(int i=0;i<owners.length();i++){JSONObject o=owners.getJSONObject(i);if(o.getString("id").isEmpty()||!ids.add(o.getString("id"))||o.getString("name").trim().isEmpty()||!email(o.getString("email")))throw new IllegalArgumentException("房東名稱、Gmail 或ID無效");}for(String key:new String[]{"properties","accounts"}){JSONArray items=rows(b,key);for(int i=0;i<items.length();i++){String id=items.getJSONObject(i).optString("ownerId");if(!id.isEmpty()&&!ids.contains(id))throw new IllegalArgumentException("不動產／帳戶的房東不存在");}}}
    public static String propertyOwner(JSONObject b,String id)throws JSONException{JSONObject p=find(rows(b,"properties"),id);return p==null?"":p.optString("ownerId");}
    public static void requireComplete(JSONObject b,String ownerId)throws JSONException{validate(b);if(find(rows(b,"owners"),ownerId)==null)throw new IllegalArgumentException("請先選擇房東");}
    private static boolean leaseOwner(JSONObject b,String leaseId,String owner)throws JSONException{JSONObject lease=find(rows(b,"leases"),leaseId);if(lease==null)return false;JSONObject unit=find(rows(b,"units"),lease.optString("unitId"));return unit!=null&&owner.equals(propertyOwner(b,unit.optString("propertyId")));}
    public static boolean accountSafe(JSONObject b,JSONObject account)throws JSONException{String owner=account.optString("ownerId"),id=account.getString("id");if(owner.isEmpty())return false;if(!account.optString("propertyId").isEmpty()&&!owner.equals(propertyOwner(b,account.optString("propertyId"))))return false;
        for(String key:new String[]{"receipts","deposits"}){JSONArray rows=rows(b,key);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(id.equals(r.optString("accountId"))&&!r.optBoolean("void")&&!leaseOwner(b,r.optString("leaseId"),owner))return false;}}
        JSONArray expenses=rows(b,"expenses");for(int i=0;i<expenses.length();i++){JSONObject e=expenses.getJSONObject(i);if(!id.equals(e.optString("accountId"))||e.optBoolean("void"))continue;JSONArray splits=e.getJSONArray("splits");for(int j=0;j<splits.length();j++)if(!owner.equals(propertyOwner(b,splits.getJSONObject(j).getString("propertyId"))))return false;}
        JSONArray transfers=rows(b,"transfers");for(int i=0;i<transfers.length();i++){JSONObject t=transfers.getJSONObject(i);if(t.optBoolean("void"))continue;String other=id.equals(t.optString("fromId"))?t.optString("toId"):id.equals(t.optString("toId"))?t.optString("fromId"):"";if(!other.isEmpty()){JSONObject a=find(rows(b,"accounts"),other);if(a==null||!owner.equals(a.optString("ownerId")))return false;}}
        JSONArray settlements=rows(b,"settlements");for(int i=0;i<settlements.length();i++){JSONObject settlement=settlements.getJSONObject(i);JSONArray payments=settlement.getJSONArray("payments");for(int j=0;j<payments.length();j++)if(id.equals(payments.getJSONObject(j).optString("accountId"))&&!leaseOwner(b,settlement.optString("leaseId"),owner))return false;}return true;
    }
    public static void paymentAccount(JSONObject b,String propertyId,String accountId)throws JSONException{JSONObject account=find(rows(b,"accounts"),accountId);String owner=propertyOwner(b,propertyId);if(account!=null&&!owner.isEmpty()&&!account.optString("ownerId").isEmpty()&&!owner.equals(account.optString("ownerId")))throw new IllegalArgumentException("付款／收款帳戶與不動產分屬不同房東，請重新選擇");}
}
